import{_ as a,o,c as t,a5 as r}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"TikTools を使う","description":"","frontmatter":{"title":"TikTools を使う","docId":"user.overview","translationKey":"user.overview","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"72ce37218d4f3341fccd306bd0b1b4039ec6e1fd3dcfeb16f9096f43576c861d","translationRevision":"da4834c0b88da318a77e43844ebda9035a55765fd62963bde508ff3075d3d823","order":0},"headers":[],"relativePath":"ja/user/index.md","filePath":"ja/user/index.md","lastUpdated":1794611623000}'),i={name:"ja/user/index.md"};function s(l,e,n,d,u,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="use-tiktools" tabindex="-1">TikTools を使う <a class="header-anchor" href="#use-tiktools" aria-label="Permalink to &quot;TikTools を使う {#use-tiktools}&quot;">​</a></h1><p>TikTools は Windows または Linux のデスクトップを TikTok LIVE に接続し、イベントの表示、視聴者ポイントの保持、PC 上でのルール実行を行います。デスクトップ画面と任意のヘッドレスホストは同じ Rust コアを共有します。Cloud アカウントは TikTok 接続とは別です。</p><h2 id="choose-your-first-task" tabindex="-1">最初の作業を選ぶ <a class="header-anchor" href="#choose-your-first-task" aria-label="Permalink to &quot;最初の作業を選ぶ {#choose-your-first-task}&quot;">​</a></h2><ol><li><a href="./requirements.html">動作要件</a> を確認し、<a href="./installation.html">公開済みバイナリをインストール</a> します。デスクトップ版の利用に Rust、Cargo、Bun は不要です。</li><li><a href="./first-live.html">LIVE に接続</a> します。ゲスト参加できるルームなら TikTok Cookie なしで始めます。</li><li><strong>ライブフィード</strong> でイベントを確認します。<strong>ポイント</strong> は視聴者の合計、<strong>分析</strong> は統計を表示します。<strong>自動化</strong> はトリガーを設定済みアクションに結び付けます。</li><li><strong>プラグイン</strong> から任意の連携をインストールします。外部プラグインはアプリと別に配布されます。</li><li><strong>オーバーレイ</strong> で OBS のブラウザーソースを準備します。ウィジェットのライブ配信にはゲートウェイ連携が必要です。</li></ol><h2 id="available-and-experimental-features" tabindex="-1">利用可能な機能と実験的な機能 <a class="header-anchor" href="#available-and-experimental-features" aria-label="Permalink to &quot;利用可能な機能と実験的な機能 {#available-and-experimental-features}&quot;">​</a></h2><p>メインナビゲーションにはライブフィード、ポイント、分析、接続、自動化、プラグイン、オーバーレイ、設定があります。ランキングと競技にはネイティブエンジンと直接アクセス用ルートがありますが、管理ページは通常のナビゲーションにまだ表示されません。古い設計書の試作機能がすべて公開済みとは限りません。</p><p>Cloud のプラグイン変更と確認付き変数操作は、各セクションの明示的な操作を使います。自動化では現在、ローカルの基準コピーと比較します。そのボタンでプロファイルを Cloud 公開することはありません。共同操作の通信と一部のインストーラーへの引き渡しは実験段階です。無効な操作欄は、多くの場合ホスト機能不足か前提条件の未達を示します。</p><h2 id="when-something-fails" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;問題が起きたとき {#when-something-fails}&quot;">​</a></h2><p><strong>診断</strong> を開き、エラーの発生元と要求 ID、インストール済みバージョンを記録します。Cookie、招待トークン、非公開の変数値は含めないでください。各ガイドの対処から始め、必要に応じてサポートガイドを使います。対話型デモは架空のデータを使うため、TikTok アカウント、OBS、ネットワークの動作を確認するものではありません。</p><p>ソース開発には別の<a href="./../developer/">開発者向けドキュメント</a> を使ってください。</p>',10)])])}const k=a(i,[["render",s]]);export{f as __pageData,k as default};
